<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/finance.php';
$userId=current_user_id(); $pdo=database(); $errors=[]; $flash=get_flash(); $editing=null;
$form=['id'=>'','source'=>'','destination'=>'','amount'=>'','date'=>date('Y-m-d'),'description'=>'','notes'=>''];
function valid_transfer_value(string $value): bool { return (bool)preg_match('/^\d{1,12}(?:\.\d{1,2})?$/',$value)&&(float)$value>0; }
function valid_transfer_date(string $value): bool { $d=DateTimeImmutable::createFromFormat('!Y-m-d',$value);$e=DateTimeImmutable::getLastErrors();return $d instanceof DateTimeImmutable&&($e===false||(!$e['warning_count']&&!$e['error_count']))&&$d->format('Y-m-d')===$value; }
function owned_transfer(PDO $pdo,int $id,int $user): ?array { $s=$pdo->prepare('SELECT id,source_wallet_id,destination_wallet_id,amount,transfer_date,description,notes FROM transfers WHERE id=:id AND user_id=:user');$s->execute(['id'=>$id,'user'=>$user]);return $s->fetch()?:null; }
if(empty($_SESSION['transfer_form_token'])) $_SESSION['transfer_form_token']=bin2hex(random_bytes(16));
if($_SERVER['REQUEST_METHOD']==='POST') { $action=(string)($_POST['action']??''); if(!verify_csrf_token($_POST['csrf_token']??null))$errors[]='Your form expired. Please try again.'; elseif($action==='delete'){ $id=filter_var($_POST['transfer_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id||!owned_transfer($pdo,$id,$userId))$errors[]='That transfer was not found.';else{try{$pdo->beginTransaction();$s=$pdo->prepare('DELETE FROM transfers WHERE id=:id AND user_id=:user');$s->execute(['id'=>$id,'user'=>$userId]);$pdo->commit();set_flash('success','Transfer deleted. Wallet balances were recalculated.');redirect('transfers.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='We could not delete this transfer.';}} } elseif(in_array($action,['create','update'],true)){ $form=['id'=>(string)($_POST['transfer_id']??''),'source'=>(string)($_POST['source_wallet_id']??''),'destination'=>(string)($_POST['destination_wallet_id']??''),'amount'=>trim((string)($_POST['amount']??'')),'date'=>(string)($_POST['transfer_date']??''),'description'=>trim((string)($_POST['description']??'')),'notes'=>trim((string)($_POST['notes']??''))]; if($action==='create'&&!hash_equals($_SESSION['transfer_form_token'],(string)($_POST['transfer_form_token']??'')))$errors[]='This transfer was already submitted or the form expired.'; $source=filter_var($form['source'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$destination=filter_var($form['destination'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$sourceWallet=$source?find_owned_wallet($pdo,$source,$userId):null;$destinationWallet=$destination?find_owned_wallet($pdo,$destination,$userId):null;if(!$sourceWallet||$sourceWallet['is_archived']||!$destinationWallet||$destinationWallet['is_archived'])$errors[]='Choose two of your active wallets.';if($source&&$destination&&$source===$destination)$errors[]='Source and destination wallets must be different.';if(!valid_transfer_value($form['amount']))$errors[]='Amount must be greater than zero.';if(!valid_transfer_date($form['date']))$errors[]='Enter a valid transfer date.';if(mb_strlen($form['description'])>150||mb_strlen($form['notes'])>5000)$errors[]='Description or notes are too long.';$id=$action==='update'?filter_var($form['id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]):null;if($action==='update'&&(!$id||!owned_transfer($pdo,$id,$userId)))$errors[]='That transfer was not found.';if(!$errors)try{$pdo->beginTransaction();if($action==='create'){$s=$pdo->prepare('INSERT INTO transfers (user_id,source_wallet_id,destination_wallet_id,amount,transfer_date,description,notes) VALUES (:user,:source,:destination,:amount,:date,:description,:notes)');$s->execute(['user'=>$userId,'source'=>$source,'destination'=>$destination,'amount'=>$form['amount'],'date'=>$form['date'],'description'=>$form['description']!==''?$form['description']:'Wallet transfer','notes'=>$form['notes']!==''?$form['notes']:null]);unset($_SESSION['transfer_form_token']);set_flash('success','Transfer recorded. Combined balance is unchanged.');}else{$s=$pdo->prepare('UPDATE transfers SET source_wallet_id=:source,destination_wallet_id=:destination,amount=:amount,transfer_date=:date,description=:description,notes=:notes WHERE id=:id AND user_id=:user');$s->execute(['source'=>$source,'destination'=>$destination,'amount'=>$form['amount'],'date'=>$form['date'],'description'=>$form['description']!==''?$form['description']:'Wallet transfer','notes'=>$form['notes']!==''?$form['notes']:null,'id'=>$id,'user'=>$userId]);set_flash('success','Transfer updated. Wallet balances were recalculated.');}$pdo->commit();redirect('transfers.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='We could not save this transfer.';}} }
$wallets=$pdo->prepare('SELECT id,wallet_name FROM wallets WHERE user_id=:user AND is_archived=0 ORDER BY wallet_name');$wallets->execute(['user'=>$userId]);$walletOptions=$wallets->fetchAll();if(isset($_GET['edit'])){$id=filter_var($_GET['edit'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$editing=$id?owned_transfer($pdo,$id,$userId):null;if(!$editing){set_flash('error','That transfer was not found.');redirect('transfers.php');}$form=['id'=>(string)$editing['id'],'source'=>(string)$editing['source_wallet_id'],'destination'=>(string)$editing['destination_wallet_id'],'amount'=>(string)$editing['amount'],'date'=>$editing['transfer_date'],'description'=>$editing['description'],'notes'=>(string)$editing['notes']];}
$history=$pdo->prepare('SELECT tr.id,tr.amount,tr.transfer_date,tr.description,sw.wallet_name source_name,dw.wallet_name destination_name FROM transfers tr JOIN wallets sw ON sw.id=tr.source_wallet_id AND sw.user_id=tr.user_id JOIN wallets dw ON dw.id=tr.destination_wallet_id AND dw.user_id=tr.user_id WHERE tr.user_id=:user ORDER BY tr.transfer_date DESC,tr.id DESC');$history->execute(['user'=>$userId]);$transfers=$history->fetchAll();$pageTitle='xinPHP | Transfers';require __DIR__.'/includes/header.php';
?>
<body class="min-h-screen bg-sand text-ink"><main class="mx-auto max-w-6xl px-6 py-10"><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-extrabold uppercase tracking-[.18em] text-brand">Move money</p><h1 class="mt-2 text-4xl font-extrabold tracking-[-.05em]">Wallet transfers</h1><p class="mt-2 text-sm text-muted">Transfers move money between your wallets and never affect income, expenses, or budgets.</p></div><a class="rounded-xl border border-line px-4 py-3 text-sm font-bold" href="wallets.php">Back to wallets</a></div><?php if($flash): ?><div class="alert <?= $flash['type']==='success'?'alert-success':'alert-error' ?> mt-6"><?= e($flash['message']) ?></div><?php endif; ?><?php if($errors): ?><div class="alert alert-error mt-6"><ul class="list-inside list-disc"><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><section class="mt-8 rounded-2xl border border-line bg-white p-6 shadow-sm"><h2 class="font-extrabold"><?= $editing?'Edit transfer':'Record a transfer' ?></h2><form class="mt-5 grid gap-4 sm:grid-cols-2" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="transfer_form_token" value="<?= e($_SESSION['transfer_form_token']) ?>"><input type="hidden" name="action" value="<?= $editing?'update':'create' ?>"><?php if($editing): ?><input type="hidden" name="transfer_id" value="<?= e($form['id']) ?>"><?php endif; ?><label class="text-sm font-bold">Source wallet<select class="mt-1 block w-full rounded-xl border border-line px-3 py-2 font-normal" name="source_wallet_id" required><option value="">Select</option><?php foreach($walletOptions as $w): ?><option value="<?= (int)$w['id'] ?>" <?= $form['source']===(string)$w['id']?'selected':'' ?>><?= e($w['wallet_name']) ?></option><?php endforeach; ?></select></label><label class="text-sm font-bold">Destination wallet<select class="mt-1 block w-full rounded-xl border border-line px-3 py-2 font-normal" name="destination_wallet_id" required><option value="">Select</option><?php foreach($walletOptions as $w): ?><option value="<?= (int)$w['id'] ?>" <?= $form['destination']===(string)$w['id']?'selected':'' ?>><?= e($w['wallet_name']) ?></option><?php endforeach; ?></select></label><label class="text-sm font-bold">Amount (PHP)<input class="mt-1 block w-full rounded-xl border border-line px-3 py-2 font-normal" name="amount" value="<?= e($form['amount']) ?>" inputmode="decimal" required></label><label class="text-sm font-bold">Transfer date<input class="mt-1 block w-full rounded-xl border border-line px-3 py-2 font-normal" name="transfer_date" type="date" value="<?= e($form['date']) ?>" required></label><label class="text-sm font-bold sm:col-span-2">Description <span class="font-normal text-muted">(optional)</span><input class="mt-1 block w-full rounded-xl border border-line px-3 py-2 font-normal" name="description" value="<?= e($form['description']) ?>" placeholder="e.g. Move savings to BDO"></label><label class="text-sm font-bold sm:col-span-2">Notes <span class="font-normal text-muted">(optional)</span><textarea class="mt-1 block min-h-20 w-full rounded-xl border border-line px-3 py-2 font-normal" name="notes"><?= e($form['notes']) ?></textarea></label><div class="sm:col-span-2 flex gap-3"><button class="rounded-xl bg-brand px-5 py-3 text-sm font-bold text-white hover:bg-brand-dark" <?= count($walletOptions)<2?'disabled':'' ?>><?= $editing?'Save changes':'Record transfer' ?></button><?php if($editing): ?><a class="px-4 py-3 text-sm font-bold text-muted" href="transfers.php">Cancel</a><?php endif; ?></div></form></section><section class="mt-10"><h2 class="text-xl font-extrabold">Transfer history</h2><?php if(!$transfers): ?><div class="mt-4 rounded-2xl border border-dashed border-line bg-white p-8 text-center"><p class="font-bold">No transfers yet</p><p class="mt-2 text-sm text-muted">Use the form above to move money between your wallets.</p></div><?php else: ?><div class="mt-4 overflow-x-auto rounded-2xl border border-line bg-white"><table class="min-w-full text-left text-sm"><thead class="border-b border-line bg-sand text-xs uppercase text-muted"><tr><th class="px-5 py-4">From</th><th class="px-5 py-4">To</th><th class="px-5 py-4">Date</th><th class="px-5 py-4">Description</th><th class="px-5 py-4 text-right">Amount</th><th></th></tr></thead><tbody><?php foreach($transfers as $tr): ?><tr class="border-b border-line last:border-0"><td class="px-5 py-4 font-bold"><?= e($tr['source_name']) ?></td><td class="px-5 py-4 font-bold"><?= e($tr['destination_name']) ?></td><td class="px-5 py-4 text-muted"><?= e($tr['transfer_date']) ?></td><td class="px-5 py-4 text-muted"><?= e($tr['description']) ?></td><td class="px-5 py-4 text-right font-bold text-brand"><?= format_peso((string)$tr['amount']) ?></td><td class="px-5 py-4"><a class="font-bold text-brand" href="transfers.php?edit=<?= (int)$tr['id'] ?>">Edit</a><form class="inline ml-3" method="post" onsubmit="return confirm('Delete this transfer?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="transfer_id" value="<?= (int)$tr['id'] ?>"><button class="font-bold text-rose-700">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></main><?php require __DIR__.'/includes/footer.php'; ?>
